     1→import { NavigationContainerRef } from "modules/navigation/const";
     2→import { Platform } from "react-native";
     3→import RNCallKeep, { CONSTANTS, type IOptions } from "react-native-callkeep";
     4→
     5→type ActiveCallInfo = {
     6→  roomId: string;
     7→  roomName: string;
     8→  senderDisplayName: string;
     9→};
    10→
    11→/** Generate a UUID v4 string for CallKit call identifiers */
    12→const generateUUID = (): string => {
    13→  return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (c) => {
    14→    const r = (Math.random() * 16) | 0;
    15→    const v = c === "x" ? r : (r & 0x3) | 0x8;
    16→    return v.toString(16);
    17→  });
    18→};
    19→
    20→export class CallKitService {
    21→  private static isSetUp = false;
    22→  private static activeCallMap = new Map<string, ActiveCallInfo>();
    23→  private static ringTimeouts = new Map<
    24→    string,
    25→    ReturnType<typeof setTimeout>
    26→  >();
    27→
    28→  /** Configure RNCallKeep. Must be called once before displaying calls. */
    29→  static async setup() {
    30→    if (Platform.OS !== "ios" || this.isSetUp) return;
    31→
    32→    try {
    33→      const options: IOptions = {
    34→        ios: {
    35→          appName: "Cloak",
    36→          supportsVideo: true,
    37→          includesCallsInRecents: true,
    38→        },
    39→        /**TODO: Android options are not configured yet */
    40→        android: {
    41→          alertTitle: "Cloak",
    42→          alertDescription: "You have a call",
    43→          cancelButton: "Decline",
    44→          okButton: "Answer",
    45→          additionalPermissions: [],
    46→        },
    47→      };
    48→      await RNCallKeep.setup(options);
    49→      this.isSetUp = true;
    50→      this.registerEventListeners();
    51→    } catch (error) {
    52→      console.error("[CallKit] Failed to setup:", error);
    53→    }
    54→  }
    55→
    56→  /** Display the native iOS incoming call screen */
    57→  static displayIncomingCall(callInfo: {
    58→    roomId: string;
    59→    roomName: string;
    60→    senderDisplayName: string;
    61→  }) {
    62→    if (Platform.OS !== "ios") return;
    63→
    64→    const callUUID = generateUUID();
    65→
    66→    this.activeCallMap.set(callUUID, {
    67→      roomId: callInfo.roomId,
    68→      roomName: callInfo.roomName,
    69→      senderDisplayName: callInfo.senderDisplayName,
    70→    });
    71→
    72→    RNCallKeep.displayIncomingCall(
    73→      callUUID,
    74→      callInfo.roomId,
    75→      callInfo.senderDisplayName,
    76→      "generic",
    77→      true,
    78→    );
    79→
    80→    // Ring timeout: auto-end after 90 seconds if not answered
    81→    const timeout = setTimeout(() => {
    82→      RNCallKeep.reportEndCallWithUUID(
    83→        callUUID,
    84→        CONSTANTS.END_CALL_REASONS.UNANSWERED,
    85→      );
    86→      this.activeCallMap.delete(callUUID);
    87→      this.ringTimeouts.delete(callUUID);
    88→    }, 90000);
    89→
    90→    this.ringTimeouts.set(callUUID, timeout);
    91→  }
    92→
    93→  /** End all active CallKit calls and clean up state */
    94→  static endAllCalls() {
    95→    if (Platform.OS !== "ios") return;
    96→
    97→    RNCallKeep.endAllCalls();
    98→
    99→    for (const [, timeout] of this.ringTimeouts) {
   100→      clearTimeout(timeout);
   101→    }
   102→    this.ringTimeouts.clear();
   103→    this.activeCallMap.clear();
   104→  }
   105→
   106→  /** Check if there is an active ringing call */
   107→  static hasActiveCall() {
   108→    return this.activeCallMap.size > 0;
   109→  }
   110→
   111→  /** Check if we already have a ringing call for a given room */
   112→  static isRingingForRoom(roomId: string) {
   113→    for (const [, info] of this.activeCallMap) {
   114→      if (info.roomId === roomId) return true;
   115→    }
   116→
   117→    return false;
   118→  }
   119→
   120→  /** Track UUIDs we are ending ourselves so the endCall listener can ignore them */
   121→  private static selfEndingCalls = new Set<string>();
   122→
   123→  private static registerEventListeners() {
   124→    // User answered the call from CallKit UI
   125→    RNCallKeep.addEventListener("answerCall", ({ callUUID }) => {
   126→      const callInfo = this.activeCallMap.get(callUUID);
   127→      if (!callInfo) return;
   128→
   129→      // Clear ring timeout
   130→      const timeout = this.ringTimeouts.get(callUUID);
   131→      if (timeout) {
   132→        clearTimeout(timeout);
   133→        this.ringTimeouts.delete(callUUID);
   134→      }
   135→
   136→      // CRITICAL WORKAROUND: CallKit takes exclusive audio control which
   137→      // breaks WebView-based audio/video. We must end the CallKit session
   138→      // before opening Element Call WebView.
   139→      // We use endCall() (not reportEndCallWithUUID) so the call is properly
   140→      // recorded as "answered" in iPhone's Phone recents, not as "missed".
   141→      // A delay lets CallKit register the answered state first.
   142→      this.selfEndingCalls.add(callUUID);
   143→
   144→      setTimeout(() => {
   145→        RNCallKeep.endCall(callUUID);
   146→      }, 300);
   147→
   148→      // Navigate to Element Call after audio session is released
   149→      setTimeout(() => {
   150→        NavigationContainerRef.navigate("elementCall", {
   151→          roomId: callInfo.roomId,
   152→          roomName: callInfo.roomName,
   153→        });
   154→      }, 800);
   155→
   156→      this.activeCallMap.delete(callUUID);
   157→    });
   158→
   159→    // User declined the call from CallKit UI (or call ended by us after answer)
   160→    RNCallKeep.addEventListener("endCall", ({ callUUID }) => {
   161→      // If we ended this call ourselves (after answering), just clean up the flag
   162→      if (this.selfEndingCalls.has(callUUID)) {
   163→        this.selfEndingCalls.delete(callUUID);
   164→        return;
   165→      }
   166→
   167→      const callInfo = this.activeCallMap.get(callUUID);
   168→      if (!callInfo) return;
   169→
   170→      // Clear ring timeout
   171→      const timeout = this.ringTimeouts.get(callUUID);
   172→      if (timeout) {
   173→        clearTimeout(timeout);
   174→        this.ringTimeouts.delete(callUUID);
   175→      }
   176→
   177→      this.activeCallMap.delete(callUUID);
   178→    });
   179→
   180→    // User tapped a call entry in iPhone's Phone recents to call back
   181→    RNCallKeep.addEventListener(
   182→      "didReceiveStartCallAction",
   183→      ({ handle }: { handle: string }) => {
   184→        // The handle is the roomId we passed to displayIncomingCall
   185→        if (!handle) return;
   186→
   187→        NavigationContainerRef.navigate("elementCall", {
   188→          roomId: handle,
   189→        });
   190→
   191→        // End the outgoing CallKit session since Element Call WebView handles it
   192→        RNCallKeep.endAllCalls();
   193→      },
   194→    );
   195→  }
   196→}
