     1→import { useIsFocused } from "@react-navigation/native";
     2→import { useAtom, useAtomValue } from "jotai";
     3→import { type FC, useEffect, useMemo } from "react";
     4→import { useAppLifecycle } from "react-native-applifecycle";
     5→import { PushNotificationsAtoms } from "../jotai";
     6→import { PushNotificationsService } from "../service";
     7→import { PushNotificationServiceController } from "./fragments";
     8→
     9→export const PushNotificationsProvider: FC = () => {
    10→  const isFocused = useIsFocused();
    11→  const hasAllowedNotificationsIntro = useAtomValue(
    12→    PushNotificationsAtoms.hasAllowedNotificationsIntro,
    13→  );
    14→  const [permissions, setPermissions] = useAtom(
    15→    PushNotificationsAtoms.isPermitted,
    16→  );
    17→  const currentLifecycle = useAppLifecycle();
    18→  const isActive = useMemo(
    19→    () => currentLifecycle === "active",
    20→    [currentLifecycle],
    21→  );
    22→
    23→  /**First time when the app is opened, the user is asked for permissions, later when the user changes the permissions in settings, the permissions are checked.*/
    24→  async function getPermissions(type: "request" | "check") {
    25→    const getPermission =
    26→      type === "request"
    27→        ? PushNotificationsService.requestPermissions
    28→        : PushNotificationsService.checkPermissions;
    29→
    30→    try {
    31→      const permissions = await getPermission();
    32→      setPermissions(permissions);
    33→    } catch (e) {
    34→      console.warn(e);
    35→    }
    36→  }
    37→
    38→  useEffect(() => {
    39→    if (!isFocused || !hasAllowedNotificationsIntro) return;
    40→
    41→    getPermissions("request");
    42→  }, [isFocused, hasAllowedNotificationsIntro]);
    43→
    44→  useEffect(() => {
    45→    if (!isActive || !isFocused || permissions === null) return;
    46→
    47→    getPermissions("check");
    48→  }, [isActive, isFocused, permissions]);
    49→
    50→  return <PushNotificationServiceController />;
    51→};
