     9→
    10→type CreatePayload = {
    11→  message: string;
    12→  title?: string;
    13→  data?: Notification["data"];
    14→  id: string;
    15→};
    16→
    17→export class NotifeeService {
    18→  private static channelId = "local-push-notifications";
    19→
    20→  // Store pending room navigation for when app is opened from notification
    21→  // This is consumed by the Splash screen after session restoration
    22→  private static pendingRoomId: string | null = null;
    23→
    24→  public static init = async () => {
    25→    await notifee.createChannel({
    26→      id: "local-push-notifications",
    27→      name: "Local push notifications",
    28→      sound: "default",
    29→      importance: AndroidImportance.HIGH,
    30→      visibility: AndroidVisibility.PUBLIC,
    31→    });
    32→
    33→    // Handle notification press when app is in foreground
    34→    notifee.onForegroundEvent((event) => {
    35→      if (event.type === EventType.PRESS) {
    36→        this.handleNotificationPress(event.detail.notification, false);
