   133→    func removeDeliveredNotificationsForFullyReadRooms(_ rooms: [RoomSummary]) async {
   134→        let roomsToLastMessageDates = rooms
   135→            .filter { $0.hasUnreadMessages == false }
   136→            .reduce(into: [:]) { partialResult, roomSummary in
   137→                partialResult[roomSummary.id] = roomSummary.lastMessageDate
   138→            }
   139→        
   140→        let notificationsIdentifiers = await notificationCenter
   141→            .deliveredNotifications()
   142→            .filter { notification in
   143→                guard let roomID = notification.request.content.roomID,
   144→                      let lastMessageDate = roomsToLastMessageDates[roomID] else {
   145→                    return false
   146→                }
   147→                    
   148→                return notification.date <= lastMessageDate
   149→            }
   150→            .map(\.request.identifier)
