   155→    private func setPusher(with deviceToken: Data, clientProxy: ClientProxyProtocol) async -> Bool {
   156→        do {
   157→            let defaultPayload = APNSPayload(aps: APSInfo(mutableContent: 1,
   158→                                                          alert: APSAlert(locKey: "Notification",
   159→                                                                          locArgs: [])),
   160→                                             pusherNotificationClientIdentifier: clientProxy.pusherNotificationClientIdentifier)
   161→
   162→            let configuration = try await PusherConfiguration(identifiers: .init(pushkey: deviceToken.base64EncodedString(),
   163→                                                                                 appId: appSettings.pusherAppID),
   164→                                                              kind: .http(data: .init(url: appSettings.pushGatewayNotifyEndpoint.absoluteString,
   165→                                                                                      format: .eventIdOnly,
   166→                                                                                      defaultPayload: defaultPayload.toJsonString())),
   167→                                                              appDisplayName: "\(InfoPlistReader.main.bundleDisplayName) (iOS)",
   168→                                                              deviceDisplayName: UIDevice.current.name,
   169→                                                              profileTag: pusherProfileTag(),
   170→                                                              lang: Bundle.app.preferredLocalizations.first ?? "en")
   171→            try await clientProxy.setPusher(with: configuration)
   172→            MXLog.info("Set pusher succeeded")
   173→            return true
   174→        } catch {
   175→            MXLog.error("Set pusher failed: \(error)")
   176→            return false
   177→        }
   178→    }
   179→
   180→    private func pusherProfileTag() -> String {
   181→        if let currentTag = appSettings.pusherProfileTag {
   182→            return currentTag
   183→        }
   184→        let chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
   185→        let newTag = (0..<16).map { _ in
   186→            let offset = Int.random(in: 0..<chars.count)
   187→            return String(chars[chars.index(chars.startIndex, offsetBy: offset)])
   188→        }.joined()
   189→
   190→        appSettings.pusherProfileTag = newTag
   191→        return newTag
   192→    }
