    22→  useEffect(() => {
    23→    if (!permissions || !!token) return;
    24→
    25→    const getFCMToken = async () => {
    26→      try {
    27→        const fcmToken = await PushNotificationsService.getToken();
    28→        setToken(fcmToken);
    29→      } catch (e) {
    30→        console.warn("Failed to get FCM token:", e);
    31→      }
    32→    };
    33→    getFCMToken();
    34→  }, [permissions, token, setToken]);
    35→
    36→  // Handle pusher registration/unregistration based on permissions
    37→  useEffect(() => {
    38→    if (!token || !permissions || !client) return;
    39→
    40→    const handlePusherState = async () => {
    41→      try {
    42→        // Check if pusher is already registered on the server
    43→        const isRegistered = await MatrixNotificationService.isPusherRegistered(token);
