    51→
    52→        if (!permissions && isRegistered) {
    53→          await PushNotificationsService.unregisterPusher();
    54→        }
    55→      } catch (e) {
    56→        console.warn("Failed to handle pusher state:", e);
    57→      }
    58→    };
    59→
    60→    handlePusherState();
    61→  }, [token, permissions, client]);
    62→
    63→  return <></>;
    64→};
