    37→      const isEncrypted = encryptionState === EncryptionState.Encrypted;
    38→      const intent = await this.resolveCallIntent(room);
    39→
    40→      const options: VirtualElementCallWidgetProperties = {
    41→        elementCallUrl: "https://call.element.io/room",
    42→        widgetId: `element-call-${roomId}`,
    43→        fontScale: 1,
    44→        parentUrl: undefined,
